from __future__ import annotations

from typing import Any


def _tool(name: str, description: str, properties: dict[str, Any], *, required: list[str] | None = None, condition: dict[str, Any] | None = None, read_only: bool = False, destructive: bool = False, idempotent: bool = False, open_world: bool = False) -> dict[str, Any]:
    schema: dict[str, Any] = {"type": "object", "properties": properties, "additionalProperties": False}
    if required:
        schema["required"] = required
    if condition:
        schema.update(condition)
    return {
        "name": name,
        "description": description,
        "inputSchema": schema,
        "annotations": {
            "readOnlyHint": read_only,
            "destructiveHint": destructive,
            "idempotentHint": idempotent,
            "openWorldHint": open_world,
        },
    }


ROOT = {"type": "string", "minLength": 1}
